/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, inject, OnDestroy, signal } from '@angular/core';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslocoPipe } from '@jsverse/transloco';
import { filter, firstValueFrom } from 'rxjs';
import { OfflineQueueService, OfflineSyncMode } from '@shared/data/offline/offline-queue.service';
import { OfflineOp } from '@shared/data/offline/offline.model';
import { ConfirmDialogService } from '@shared/toolkit/dialog/confirm-dialog.service';
import { EditConflictService } from '@shared/toolkit/edit-conflict/edit-conflict.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { OfflineEditDialogComponent, OfflineEditDialogData } from './offline-edit-dialog.component';

/** Estado de una fila: el de la cola o, en la sincronización en curso, subiendo o subida. */
export type OfflineRowState = 'pending' | 'failed' | 'blocked' | 'running' | 'done';

export interface OfflineRow {
  op: OfflineOp;
  state: OfflineRowState;
}

const STATE_ICONS: Record<OfflineRowState, string> = {
  pending: 'schedule',
  running: 'progress_activity',
  done: 'check_circle',
  failed: 'error',
  blocked: 'block',
};

/** Estado HTTP de un conflicto de edición (bloqueo optimista). */
const PRECONDITION_FAILED = 412;

/**
 * Cambios pendientes de subir: la lista por orden, la subida una a una con su progreso y, si algo falla, las
 * acciones para resolverlo (reintentar, corregir los datos, resolver el conflicto, descartar o seguir con el resto).
 */
@Component({
  selector: 'offline-sync-dialog',
  standalone: true,
  imports: [MatDialogModule, MatButtonModule, MatIconModule, MatProgressBarModule, MatTooltipModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './offline-sync-dialog.component.html',
  styleUrl: './offline-sync-dialog.component.scss',
})
export class OfflineSyncDialogComponent implements OnDestroy {
  readonly queue = inject(OfflineQueueService);
  private readonly dialog = inject(MatDialog);
  private readonly confirm = inject(ConfirmDialogService);
  private readonly conflicts = inject(EditConflictService);
  private readonly notify = inject(NotifyService);

  readonly icons = STATE_ICONS;
  /** Operaciones al empezar la última sincronización: las subidas siguen en la lista con su marca. */
  private readonly snapshot = signal<OfflineOp[]>(this.queue.ops());
  readonly busy = signal(false);

  readonly syncing = computed(() => this.queue.syncState() === 'syncing');

  readonly rows = computed<OfflineRow[]>(() => {
    const run = this.queue.run();
    const current = new Map(this.queue.ops().map((op) => [op.seq!, op]));
    const done = this.snapshot()
      .filter((op) => !current.has(op.seq!) && run.get(op.seq!) === 'done')
      .map((op) => ({ op, state: 'done' as const }));
    const left = [...current.values()].map((op) => ({
      op,
      state: run.get(op.seq!) === 'running' ? ('running' as const) : op.status,
    }));
    return [...done, ...left].sort((a, b) => a.op.seq! - b.op.seq!);
  });

  readonly progress = computed(() => {
    const rows = this.rows();
    return rows.length ? (100 * rows.filter((row) => row.state === 'done').length) / rows.length : 100;
  });

  /** Mensaje de estado bajo el título. */
  readonly status = computed(() => {
    const state = this.queue.syncState();
    if (state === 'syncing') {
      return 'offline.sync.state.syncing';
    }
    if (!this.queue.online() || state === 'offline') {
      return 'offline.sync.state.offline';
    }
    if (this.queue.failed()) {
      return 'offline.sync.state.failed';
    }
    if (!this.queue.pending()) {
      return 'offline.sync.state.empty';
    }
    return this.queue.autoSyncArmed() ? 'offline.sync.state.auto' : 'offline.sync.state.pending';
  });

  ngOnDestroy(): void {
    this.queue.resetRun();
  }

  async sync(mode: OfflineSyncMode = 'retry'): Promise<void> {
    this.snapshot.set(this.queue.ops());
    const result = await this.queue.sync(mode);
    if (result === 'done') {
      this.notify.success('offline.notify.synced');
    }
  }

  /** Descarta la operación y, tras confirmarlo, todas las que dependen de ella. */
  async discard(op: OfflineOp): Promise<void> {
    const dependents = this.queue.dependents(op);
    const ok = await firstValueFrom(
      this.confirm.confirm({
        titleKey: 'offline.discard.title',
        messageKey: dependents.length ? 'offline.discard.withDependents' : 'offline.discard.message',
        okKey: 'offline.discard.ok',
        params: { label: op.label, count: dependents.length },
      }),
    );
    if (ok) {
      await this.queue.discard(op);
    }
  }

  /** Corrige los datos de la operación a mano. */
  async edit(op: OfflineOp): Promise<void> {
    const data: OfflineEditDialogData = { op };
    const payload = await firstValueFrom(
      this.dialog
        .open(OfflineEditDialogComponent, { data, width: '640px', maxWidth: '95vw' })
        .afterClosed()
        .pipe(filter((value) => value !== undefined)),
      { defaultValue: undefined },
    );
    if (payload !== undefined) {
      await this.queue.edit(op, payload);
    }
  }

  /** Conflicto con el servidor: fusión a tres bandas entre la base, lo enviado y lo vigente. */
  async resolveConflict(op: OfflineOp): Promise<void> {
    this.busy.set(true);
    try {
      const conflict = await this.queue.conflict(op);
      const fields = Object.keys({ ...conflict.sent, ...conflict.current })
        .filter((name) => !name.startsWith('$'))
        .map((name) => ({ name, label: name }));
      const merged = await firstValueFrom(this.conflicts.resolve(conflict, fields));
      if (merged !== null) {
        await this.queue.edit(op, merged, conflict.current);
      }
    } catch {
      this.notify.error('offline.notify.conflictUnavailable');
    } finally {
      this.busy.set(false);
    }
  }

  canEdit(op: OfflineOp): boolean {
    return op.kind !== 'delete' && op.kind !== 'file' && !!op.payload && typeof op.payload === 'object';
  }

  isConflict(op: OfflineOp): boolean {
    return op.kind === 'update' && op.error?.status === PRECONDITION_FAILED;
  }

  /** `device-instance` → `Device instance`. */
  entity(op: OfflineOp): string {
    const text = op.repo.replace(/-/g, ' ');
    return text.charAt(0).toUpperCase() + text.substring(1);
  }

  /** Texto de la fila que bloquea a esta. */
  blocker(op: OfflineOp): string {
    const blocker = this.queue.ops().find((item) => item.seq === op.blockedBy);
    return blocker ? this.entity(blocker) + ' · ' + (blocker.label ?? blocker.key) : '#' + op.blockedBy;
  }
}
